/** A section of Ithkuil text which represents a single grammatical category. */
export class DCLeaf {
    source;
    slot;
    type;
    value;
    constructor(source, slot, type, value) {
        this.source = source;
        this.slot = slot;
        this.type = type;
        this.value = value;
    }
}
/** The decomposition of the stress placed on a particular Ithkuil word. */
export class DCStress {
    stress;
    value;
    constructor(stress, value) {
        this.stress = stress;
        this.value = value;
    }
}
/**
 * A section of Ithkuil text which can further be broken down, but which is tied
 * to itself in some way.
 *
 * Examples include the VnCn compund, which uses the Cn to determine whether the
 * Vn is aspectual or not.
 */
export class DCGroup {
    type;
    items;
    constructor(type, ...items) {
        this.type = type;
        this.items = items;
    }
}
/** A completely decomposed Ithkuil word. */
export class DCWord {
    kind;
    stress;
    items;
    constructor(kind, stress, ...items) {
        this.kind = kind;
        this.stress = stress;
        this.items = items;
    }
}
